import { Segment, SfNode } from "./reader.js";
import { encodeValue, SfValue } from "./values.js";

function escapeText(text: string): string {
  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function scriptSafeJson(value: SfValue): string {
  return JSON.stringify(encodeValue(value)).replace(/</g, "\\u003c");
}

/** An island's props script: its props as the server encoded them, else encoded here. */
function propsScript(node: { props: { [key: string]: SfValue }; encoded?: unknown }): string {
  return node.encoded === undefined ? scriptSafeJson(node.props) : JSON.stringify(node.encoded).replace(/</g, "\\u003c");
}

export interface IdAlloc {
  next: number;
  /** The key of the segment being rendered, which names the placed content inside it. */
  segment?: string;
  /** The island whose own markup is being rendered, by its region key or else its id, which names the placed content it holds. */
  island?: string;
}

/** The attribute of the template `nodeToHtml` holds placed content in, in place, naming the segment that placed it. Whatever writes the markup moves the content to its target. */
export const PLACED_ATTR = "data-sf-placed";

/** The attribute of the template opening a piece of placed content at the end of the body, naming the segment that placed it, as the server writes it after the document. */
export const PLACED_OPEN = "data-sf-l";
/** The attribute of the template closing one. */
export const PLACED_END = "data-sf-l-end";
/** The attribute naming the island whose markup placed a piece, by its region key or else its id. */
export const PLACED_ISLAND = "data-sf-island";
/** The attribute naming the place a piece belongs in when it is not there yet: the id of the element a `Place` writes. */
export const PLACED_TO = "data-sf-to";

/** Client-side ids use the `sf-c` prefix so they can never collide with the server's `sf-i` sequence. */
export function nodeToHtml(node: SfNode, ids: IdAlloc): string {
  switch (node.kind) {
    case "text":
      return escapeText(node.text);
    case "raw":
      return node.html;
    case "seq":
      return node.children.map((c) => nodeToHtml(c, ids)).join("");
    case "client":
      return clientHtml(node, ids, (children) => children.map((c) => nodeToHtml(c, ids)).join(""));
    case "pending":
      return `<div data-sf-slot="${node.slot}">${nodeToHtml(node.fallback, ids)}</div>`;
    case "placed": {
      const island = ids.island ? ` ${PLACED_ISLAND}="${escapeAttr(ids.island)}"` : "";
      const to = node.target.startsWith("#") ? ` ${PLACED_TO}="${escapeAttr(node.target.slice(1))}"` : "";
      return `<template ${PLACED_ATTR}="${escapeAttr(ids.segment ?? "")}"${island}${to}>${node.children.map((c) => nodeToHtml(c, ids)).join("")}</template>`;
    }
    case "outlet":
      return "";
  }
}

function escapeAttr(value: string): string {
  return value.replace(/&/g, "&amp;").replace(/"/g, "&quot;");
}

export function escapeKey(key: string): string {
  return key.replace(/%/g, "%25").replace(/-/g, "%2D");
}

function subtreeAt(node: SfNode, path: number[]): SfNode {
  let current = node;
  for (const idx of path) {
    if (current.kind !== "seq" && current.kind !== "client") throw new Error("segment path walks through a node with no children");
    current = current.children[idx];
  }
  return current;
}

/** Mirrors the server's segment serialization: the subtree wrapped in comment delimiters, recursing into child segments, so a swapped-in region stays diffable on the next navigation. */
export function renderSegment(node: SfNode, seg: Segment, ids: IdAlloc): string {
  const outer = ids.segment;
  ids.segment = seg.k;
  let out = `<!--sf-g:${escapeKey(seg.k)}-->`;
  const inner = seg.c.find((c) => c.s === undefined && (c.p ?? []).length === 0);
  if (inner) {
    out += renderSegment(node, inner, ids);
  } else {
    const positioned = seg.c.filter((c) => c.s === undefined && (c.p ?? []).length > 0).map((c) => ({ path: c.p ?? [], seg: c }));
    out += renderPositioned(node, positioned, ids);
  }
  ids.segment = outer;
  return out + "<!--/sf-g-->";
}

/** `node` with each positioned child segment wrapped at its path, descending through seq items and an island's children alike. */
/** An island's marker around what `inner` writes of its children, then its props script. A rendered island is the island its placed content names while its children are written. */
function clientHtml(node: Extract<SfNode, { kind: "client" }>, ids: IdAlloc, inner: (children: SfNode[]) => string): string {
  const id = `sf-c${ids.next++}`;
  const outer = ids.island;
  const key = node.props[REGION_KEY];
  if (node.rendered) ids.island = typeof key === "string" ? key : id;
  const html = inner(node.children);
  ids.island = outer;
  return `<sf-i id="${id}" data-sf-module="${node.module}"${node.rendered ? ` ${SSR_ATTR}` : ""}>${html}</sf-i><script type="application/json" data-sf-props="${id}">${propsScript(node)}</script>`;
}

function renderPositioned(node: SfNode, positioned: { path: number[]; seg: Segment }[], ids: IdAlloc): string {
  if (positioned.length === 0) return nodeToHtml(node, ids);
  const items = (children: SfNode[]): string =>
    children
      .map((child, idx) => {
        const here = positioned.filter((c) => c.path[0] === idx).map((c) => ({ path: c.path.slice(1), seg: c.seg }));
        const exact = here.find((c) => c.path.length === 0);
        return exact ? renderSegment(child, exact.seg, ids) : renderPositioned(child, here, ids);
      })
      .join("");
  if (node.kind === "seq") return items(node.children);
  if (node.kind === "client") return clientHtml(node, ids, items);
  return nodeToHtml(node, ids);
}

/** The props key an island's region key rides under, written by the renderer. */
export const REGION_KEY = "$k";

/** What a payload says about one nested island region: the props to mount or patch it with, its own markup for a region that does not exist yet, the regions inside it and the markup of its children region. */
export interface RegionSource {
  props: { [key: string]: SfValue };
  /** `props` as the server encoded them, absent on a node no payload brought. */
  encoded?: unknown;
  html: string;
  nested: Map<string, RegionSource>;
  children: string | null;
  markup: { [n: string]: string } | null;
}

/** The attribute of the region an island's children render in, which the mounter hands the component as its `children`. */
/** Marks an island element whose markup the server rendered, so the browser hydrates it rather than mounting it. */
export const SSR_ATTR = "data-sf-ssr";
export const CHILDREN_ATTR = "data-sf-children";

/** The markup of an island's children region: the `<sf-s data-sf-children>` in its own markup that is not inside an island nested in it. Null for a node that is not an island or holds no such region. */
export function childrenOf(node: SfNode, ids: IdAlloc): string | null {
  if (node.kind !== "client") return null;
  const html = node.children.map((c) => nodeToHtml(c, ids)).join("");
  if (!html.includes(CHILDREN_ATTR)) return null;
  const template = document.createElement("template");
  template.innerHTML = html;
  const region = Array.from(template.content.querySelectorAll(`sf-s[${CHILDREN_ATTR}]`)).find((found) => !found.parentElement?.closest("sf-i"));
  return region ? region.innerHTML : null;
}

/** The attribute of the regions an island's markup props render in. */
export const MARKUP_ATTR = "data-sf-m";

/** The markup of each markup prop region in an island's own markup, by region number: the `<sf-s data-sf-m>` its render placed, else the `<template data-sf-m>` the server held it in, neither inside an island nested in it. Null for a node that is not an island or holds none. */
export function markupOf(node: SfNode, ids: IdAlloc): { [n: string]: string } | null {
  if (node.kind !== "client") return null;
  const html = node.children.map((c) => nodeToHtml(c, ids)).join("");
  if (!html.includes(MARKUP_ATTR)) return null;
  const template = document.createElement("template");
  template.innerHTML = html;
  const out: { [n: string]: string } = {};
  for (const region of Array.from(template.content.querySelectorAll(`sf-s[${MARKUP_ATTR}], template[${MARKUP_ATTR}]`))) {
    if (region.parentElement?.closest("sf-i")) continue;
    const n = region.getAttribute(MARKUP_ATTR) ?? "";
    if (!(n in out)) out[n] = region.innerHTML;
  }
  return out;
}

/** The island regions `node` describes, by region key: the islands directly inside it, each carrying the ones inside itself. An island's own body is where its nested regions live, so a client node is descended into rather than collected at the top. */
export function regionSources(node: SfNode, ids: IdAlloc): Map<string, RegionSource> {
  const out = new Map<string, RegionSource>();
  const walk = (n: SfNode): void => {
    switch (n.kind) {
      case "seq":
        n.children.forEach(walk);
        return;
      case "client": {
        const key = n.props[REGION_KEY];
        if (typeof key === "string") out.set(key, { props: n.props, encoded: n.encoded, html: nodeToHtml(n, ids), nested: regionSources(n, ids), children: childrenOf(n, ids), markup: markupOf(n, ids) });
        return;
      }
      case "pending":
        walk(n.fallback);
        return;
      default:
        return;
    }
  };
  if (node.kind === "client") {
    node.children.forEach(walk);
    return out;
  }
  walk(node);
  return out;
}

export { propsScript, scriptSafeJson };

export { subtreeAt };
